CREATE TYPE "AdminRole" AS ENUM ('SUPER_ADMIN','EDITOR');
CREATE TYPE "ContentStatus" AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');
CREATE TYPE "ContactStatus" AS ENUM ('NEW','READ','REPLIED','ARCHIVED');
CREATE TABLE "AdminUser" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"name" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"role" "AdminRole" NOT NULL DEFAULT 'SUPER_ADMIN',"active" BOOLEAN NOT NULL DEFAULT true,"lastLoginAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AdminUser_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AdminUser_email_key" ON "AdminUser"("email");
CREATE TABLE "AdminSession" ("id" TEXT NOT NULL,"tokenHash" TEXT NOT NULL,"adminId" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AdminSession_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AdminSession_tokenHash_key" ON "AdminSession"("tokenHash");
CREATE INDEX "AdminSession_adminId_idx" ON "AdminSession"("adminId");
CREATE INDEX "AdminSession_expiresAt_idx" ON "AdminSession"("expiresAt");
ALTER TABLE "AdminSession" ADD CONSTRAINT "AdminSession_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "AdminUser"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "ContentEntry" ("id" TEXT NOT NULL,"type" TEXT NOT NULL,"title" TEXT NOT NULL,"slug" TEXT NOT NULL,"excerpt" TEXT,"body" TEXT NOT NULL,"coverImage" TEXT,"status" "ContentStatus" NOT NULL DEFAULT 'DRAFT',"publishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ContentEntry_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ContentEntry_slug_key" ON "ContentEntry"("slug");
CREATE INDEX "ContentEntry_type_status_idx" ON "ContentEntry"("type","status");
CREATE INDEX "ContentEntry_publishedAt_idx" ON "ContentEntry"("publishedAt");
CREATE TABLE "ManagedEvent" ("id" TEXT NOT NULL,"title" TEXT NOT NULL,"slug" TEXT NOT NULL,"summary" TEXT,"description" TEXT NOT NULL,"venue" TEXT,"location" TEXT,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3),"imageUrl" TEXT,"registrationEnabled" BOOLEAN NOT NULL DEFAULT true,"registrationUrl" TEXT,"status" "ContentStatus" NOT NULL DEFAULT 'DRAFT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ManagedEvent_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "ManagedEvent_slug_key" ON "ManagedEvent"("slug");
CREATE INDEX "ManagedEvent_status_startsAt_idx" ON "ManagedEvent"("status","startsAt");
CREATE TABLE "ContactMessage" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT NOT NULL,"phone" TEXT,"subject" TEXT,"message" TEXT NOT NULL,"status" "ContactStatus" NOT NULL DEFAULT 'NEW',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ContactMessage_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ContactMessage_status_createdAt_idx" ON "ContactMessage"("status","createdAt");
CREATE INDEX "ContactMessage_email_idx" ON "ContactMessage"("email");
CREATE TABLE "MediaAsset" ("id" TEXT NOT NULL,"filename" TEXT NOT NULL,"originalName" TEXT NOT NULL,"mimeType" TEXT NOT NULL,"size" INTEGER NOT NULL,"url" TEXT NOT NULL,"altText" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "MediaAsset_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "MediaAsset_url_key" ON "MediaAsset"("url");
CREATE TABLE "SiteSetting" ("id" TEXT NOT NULL,"key" TEXT NOT NULL,"value" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SiteSetting_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "SiteSetting_key_key" ON "SiteSetting"("key");
CREATE TABLE "AuditLog" ("id" TEXT NOT NULL,"adminId" TEXT,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" TEXT,"details" JSONB,"ipAddress" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditLog_pkey" PRIMARY KEY ("id"));
CREATE INDEX "AuditLog_adminId_createdAt_idx" ON "AuditLog"("adminId","createdAt");
CREATE INDEX "AuditLog_entityType_entityId_idx" ON "AuditLog"("entityType","entityId");
ALTER TABLE "AuditLog" ADD CONSTRAINT "AuditLog_adminId_fkey" FOREIGN KEY ("adminId") REFERENCES "AdminUser"("id") ON DELETE SET NULL ON UPDATE CASCADE;